// ファイルブラウザー（Claude Code の mod）
//
// 【なぜ要るか】Desktop の Code タブでフォルダを押しても中身が開かない既知の不具合
//   （anthropics/claude-code #63353・#65655・#60450）の回避。
// 【何をするか】/files でペインを開き、セッションの作業ディレクトリの木を出す。フォルダは押すと展開・折りたたみ、
//   文字のファイル（.md .txt .csv .json .py など）は押すと中身をプレビューのペインに出し、それ以外は既定のアプリで開く。
//   各行の「外で開く」は既定のアプリ（フォルダならエクスプローラーでその場所）。
//   種類ごとのアイコン・行ごとの区切り線・触れた行の色を付ける。
//   Desktop の右の「ファイル」欄で開く口は mods の API に無い（$.ui・$.session の一覧）ので、プレビューは自前のペイン。
// 【入口】/files と、入力欄の上の帯の「ファイル一覧」ボタン（マウスだけで開ける）。
// 【線】登録するのは session.start（コマンドの登録）・command.run・ui.render（ペインと帯）だけ。道具や許可に関わる
//   イベントは登録しない。$.process.run は explorer.exe にパスを1つ渡す形だけ（シェルを通さない）。
//   作業ディレクトリの外へは出ない（$.fs.stat の realPath が作業ディレクトリの下にあるときだけ一覧・開く・読む）。
//   読むのは $.fs.read だけで、書かない。$.prompt.fill は「@<相対パス> 」を mode 'insert' で入れる1か所だけ（送らない・2026-10-08）。
// 【静的解析の決まり】$ は最上位の関数にだけ渡す・$ の名前空間を変数に入れない・on のイベント名は文字列で書く。

const PANE = 'file-browser-list'
const PREVIEW = 'file-browser-preview'
// 1つのフォルダに出す数と、木全体の行数の上限（区切り線の分も含めてペインの文字数の上限 100,000 字に収める）
const MAX_ENTRIES = 300
const MAX_ROWS = 600
// 区切り線の長さの上限（ペインの幅に合わせ、これより長くはしない）
const RULE_MAX = 60
// explorer.exe はすぐ戻る。居残る形でも画面が固まらないよう短く切る
const OPEN_TIMEOUT_MS = 5000
// プレビューで読む大きさの上限（$.fs.read は 4 MiB まで）と、描く字数の上限（1つの木で描かれるのは先頭 100,000 字）
const PREVIEW_MAX_BYTES = 4 * 1024 * 1024
const PREVIEW_MAX_CHARS = 90000
// 押すとプレビューで開く文字のファイル（小文字の拡張子）。実行されうるもの（.bat .ps1 .sh）も、ここでは読むだけ
const TEXT_EXTENSIONS = new Set(
  (
    'md markdown txt log csv tsv json jsonl yaml yml toml ini cfg conf ' +
    'py js mjs cjs ts tsx jsx html htm css scss xml svg sh bat cmd ps1 psm1 sql java c h cpp hpp cs go rs rb php r ' +
    'gitignore gitattributes editorconfig'
  ).split(/\s+/),
)
// Markdown として描く拡張子
const MARKDOWN_EXTENSIONS = new Set(['md', 'markdown'])
// 種類ごとのアイコン（拡張子 → 絵文字）
const ICONS = [
  ['🖼️', 'png jpg jpeg gif bmp webp svg ico heic tif tiff'],
  ['📊', 'ppt pptx key odp'],
  ['📈', 'xls xlsx xlsm csv tsv ods'],
  ['📕', 'pdf'],
  ['📝', 'doc docx odt rtf md markdown txt log'],
  ['💻', 'py js mjs cjs ts tsx jsx html htm css scss json jsonl yaml yml toml ini cfg conf xml sh bat cmd ps1 psm1 sql java c h cpp hpp cs go rs rb php r ipynb'],
  ['🎵', 'mp3 wav m4a flac ogg aac'],
  ['🎬', 'mp4 mov avi mkv webm wmv'],
  ['🗜️', 'zip 7z rar tar gz tgz bz2 xz'],
  ['⚙️', 'exe msi dll lnk'],
]
const ICON_OF = new Map()
for (const [icon, list] of ICONS) for (const ext of list.split(' ')) ICON_OF.set(ext, icon)

// 作業ディレクトリ（/files を打ったときに決める）: shown は見せる綴り、real は解決した先（小文字・/ 区切り）
let root = null
// 展開しているフォルダ（作業ディレクトリからの相対・/ 区切り。'' は根）
let expanded = new Set()
// フォルダごとの一覧: { entries, more } か { error }
let listings = new Map()
// 読み込み中のフォルダ
let loading = new Set()
// 最後の知らせ（開いた・開けなかった）
let notice = ''
// プレビューしているファイル: { rel, text, truncated, markdown } か { rel, error }
let preview = null

// 比べるための形（/ 区切り・末尾の / なし・小文字。Windows は大小を区別しない）
function comparable(path) {
  return String(path).replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
}

// real が根の下（根そのものを含む）か
function isInside(rootReal, real) {
  const target = comparable(real)
  return target === rootReal || target.startsWith(rootReal + '/')
}

// 相対（/ 区切り）から、見せる綴りの絶対パスへ
function absoluteOf(rel) {
  if (!rel) return root.shown
  return root.shown + root.sep + rel.split('/').join(root.sep)
}

function parentOf(rel) {
  const index = rel.lastIndexOf('/')
  return index < 0 ? '' : rel.slice(0, index)
}

function baseName(rel) {
  return rel.slice(rel.lastIndexOf('/') + 1)
}

// 拡張子（小文字・点なし）。.gitignore のような点で始まる名前は名前そのもの
function extensionOf(name) {
  const lower = name.toLowerCase()
  if (lower.startsWith('.') && lower.indexOf('.', 1) < 0) return lower.slice(1)
  const index = lower.lastIndexOf('.')
  return index <= 0 ? '' : lower.slice(index + 1)
}

function isTextFile(name) {
  return TEXT_EXTENSIONS.has(extensionOf(name))
}

function iconOf(entry) {
  if (entry.kind === 'dir') return '📁'
  if (entry.isLink) return '🔗'
  return ICON_OF.get(extensionOf(entry.name)) || '📄'
}

function messageOf(err) {
  return String((err && err.message) || err)
}

// フォルダが先、その中は名前順（日本語の並び）
function compareEntries(a, b) {
  const rank = (entry) => (entry.kind === 'dir' ? 0 : entry.isLink ? 1 : 2)
  const diff = rank(a) - rank(b)
  return diff !== 0 ? diff : a.name.localeCompare(b.name, 'ja')
}

// 押せる部品の key（パスから作る短い印。日本語の名前でも英数字になる）
function keyOf(prefix, rel) {
  let hash = 5381
  for (let i = 0; i < rel.length; i += 1) hash = ((hash * 33) ^ rel.charCodeAt(i)) >>> 0
  return prefix + '-' + hash.toString(16) + '-' + rel.length
}

// 出す行の並び（展開しているフォルダだけ辿る）
function visibleRows() {
  const rows = []
  const visit = (rel, depth) => {
    const listing = listings.get(rel)
    if (!listing) {
      rows.push({ type: 'loading', rel, depth })
      return
    }
    if (listing.error) {
      rows.push({ type: 'error', rel, depth, text: listing.error })
      return
    }
    for (const entry of listing.entries) {
      if (rows.length >= MAX_ROWS) return
      const child = rel ? rel + '/' + entry.name : entry.name
      rows.push({ type: 'entry', rel: child, depth, entry })
      if (entry.kind !== 'file' && expanded.has(child)) visit(child, depth + 1)
    }
    if (listing.more) rows.push({ type: 'more', rel, depth, count: listing.more })
  }
  visit('', 0)
  return rows
}

// 作業ディレクトリを根に決め、根の一覧を読む
async function initRoot($) {
  const cwd = await $.session.cwd()
  const stat = await $.fs.stat(cwd, { resolve: true })
  const shown = cwd.replace(/[\\/]+$/, '') || cwd
  root = { shown, real: comparable(stat.realPath || cwd), sep: cwd.includes('\\') ? '\\' : '/' }
  expanded = new Set([''])
  listings = new Map()
  loading = new Set()
  notice = ''
  await loadDir($, '')
}

// 1つのフォルダを読む（作業ディレクトリの外を指すものは読まない）
async function loadDir($, rel) {
  const path = absoluteOf(rel)
  try {
    const stat = await $.fs.stat(path, { resolve: true })
    if (stat.kind !== 'dir') {
      listings.set(rel, { error: 'フォルダではありません' })
      return
    }
    if (!stat.realPath || !isInside(root.real, stat.realPath)) {
      listings.set(rel, { error: '作業ディレクトリの外を指すので開きません' })
      return
    }
    const entries = await $.fs.list(path)
    const sorted = [...entries].sort(compareEntries)
    listings.set(rel, { entries: sorted.slice(0, MAX_ENTRIES), more: Math.max(0, sorted.length - MAX_ENTRIES) })
  } catch (err) {
    listings.set(rel, { error: '読めませんでした: ' + messageOf(err) })
  }
}

// フォルダの展開・折りたたみ
async function toggleDir($, rel) {
  if (expanded.has(rel)) {
    expanded.delete(rel)
    $.ui.invalidate('ui.render')
    return
  }
  expanded.add(rel)
  loading.add(rel)
  $.ui.invalidate('ui.render')
  await loadDir($, rel)
  loading.delete(rel)
  $.ui.invalidate('ui.render')
}

// 展開しているフォルダを全部読み直す
async function reloadAll($) {
  for (const rel of [...expanded]) await loadDir($, rel)
  notice = '読み直しました'
  $.ui.invalidate('ui.render')
}

// 外で開く（ファイルなら既定のアプリ・フォルダならその場所）。$.process.run の形はこの1つだけ
async function openInExplorer($, rel) {
  const path = absoluteOf(rel)
  try {
    const stat = await $.fs.stat(path, { resolve: true })
    if (!stat.realPath || !isInside(root.real, stat.realPath)) {
      notice = '作業ディレクトリの外を指すので開きません: ' + (rel || root.shown)
    } else if (!/^[a-z]:\//.test(comparable(path))) {
      notice = 'Windows のパスではないので開けません: ' + path
    } else if (path.includes(',')) {
      // explorer.exe は , を区切りと読むので、名前に , があると別のものを開きうる
      notice = '名前に , があるため開けません。上のフォルダの「外で開く」でエクスプローラーから開いてください: ' + rel
    } else {
      await $.process.run(['explorer.exe', path], { timeoutMs: OPEN_TIMEOUT_MS })
      notice = '開きました: ' + (rel || root.shown)
    }
  } catch (err) {
    notice = '開けませんでした: ' + (rel || root.shown) + '（' + messageOf(err) + '）'
  }
  $.ui.invalidate('ui.render')
}

// 文字のファイルをプレビューのペインに出す。大きい・文字でない・置けないときは外で開く
async function openPreview($, rel) {
  const path = absoluteOf(rel)
  try {
    const stat = await $.fs.stat(path, { resolve: true })
    if (!stat.realPath || !isInside(root.real, stat.realPath)) {
      notice = '作業ディレクトリの外を指すので開きません: ' + rel
      $.ui.invalidate('ui.render')
      return
    }
    if (stat.size > PREVIEW_MAX_BYTES) {
      notice = '大きいので外で開きます: ' + rel
      await openInExplorer($, rel)
      return
    }
    const text = String(await $.fs.read(path))
    if (text.includes('\u0000')) {
      notice = '文字のファイルではないので外で開きます: ' + rel
      await openInExplorer($, rel)
      return
    }
    const truncated = text.length > PREVIEW_MAX_CHARS
    preview = { rel, text: truncated ? text.slice(0, PREVIEW_MAX_CHARS) : text, truncated, markdown: MARKDOWN_EXTENSIONS.has(extensionOf(rel)) }
  } catch (err) {
    preview = { rel, error: '読めませんでした: ' + messageOf(err) }
  }
  const result = await $.ui.open({ id: PREVIEW, title: baseName(rel), focus: true, closeOnEscape: true })
  if (!result.isPlaced) {
    $.ui.toast('プレビューのペインを出せないので外で開きます')
    await openInExplorer($, rel)
    return
  }
  $.ui.invalidate('ui.render')
}

// ファイルを押したとき: 文字のファイルはプレビュー・それ以外は外で開く
async function pressFile($, rel) {
  if (isTextFile(baseName(rel))) {
    await openPreview($, rel)
    return
  }
  await openInExplorer($, rel)
}

// リンクは行き先を見て、フォルダなら展開・ファイルなら押したときと同じ
async function pressLink($, rel) {
  try {
    const stat = await $.fs.stat(absoluteOf(rel), { resolve: true })
    if (stat.kind === 'dir') {
      await toggleDir($, rel)
      return
    }
  } catch (err) {
    notice = '行き先の無いリンクです: ' + rel
    $.ui.invalidate('ui.render')
    return
  }
  await pressFile($, rel)
}

// 入力欄へ @参照を差し込む（mode 'insert'＝打ちかけの字は両側に残り、カーソルの位置に入る）。送りはしない。
//   $.prompt.fill の型は index.d.ts の PromptFillArgs・PromptFillMode。
//   空白を含む名前の @ の書き方は確かめていないので、入れずに知らせる（別のファイルを指すのを避ける）
async function insertReference($, rel) {
  if (!rel || /\s/.test(rel)) {
    notice = '空白を含む名前は @参照にできません。「外で開く」か、名前を打ってください: ' + (rel || root.shown)
    $.ui.invalidate('ui.render')
    return
  }
  try {
    const result = await $.prompt.fill({ text: '@' + rel + ' ', mode: 'insert' })
    if (result && result.isFilled) {
      notice = '入力欄に入れました: @' + rel
    } else {
      notice = '入力欄に入れられませんでした（入力欄が無いか、ダイアログが開いています）: @' + rel
      $.ui.toast('入力欄に入れられませんでした')
    }
  } catch (err) {
    notice = '入力欄に入れられませんでした: ' + messageOf(err)
    $.ui.toast('入力欄に入れられませんでした')
  }
  $.ui.invalidate('ui.render')
}

// ペインを開く（/files と帯のボタンの両方から）。置けなければ toast と transcript の文で知らせる
async function openFiles($) {
  try {
    await initRoot($)
  } catch (err) {
    $.ui.toast('作業ディレクトリを読めませんでした')
    return { text: '作業ディレクトリを読めませんでした: ' + messageOf(err) }
  }
  const result = await $.ui.open({ id: PANE, title: 'ファイル', focus: true, closeOnEscape: true })
  if (!result.isPlaced) {
    // 古い Desktop はペインを置かない（型の UiOpenResult）。置けなかったことを見える形で返す
    $.ui.toast('ファイルの一覧のペインを出せませんでした')
    return { text: 'ファイルの一覧のペインを出せませんでした: ' + result.reason }
  }
  return {}
}

// Markdown の囲み（中身にある最も長い ` の並びより1つ長くする）
function fenced(text, language) {
  let longest = 2
  for (const run of text.match(/`+/g) || []) longest = Math.max(longest, run.length)
  const fence = '`'.repeat(longest + 1)
  return fence + language + '\n' + text + (text.endsWith('\n') ? '' : '\n') + fence
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'files',
      description: '作業ディレクトリのファイルをペインに一覧する（文字のファイルは中で見る・ほかは既定のアプリで開く）',
      immediate: true,
    })
    return next(e)
  })

  on('command.run', { command: 'files' }, async ($) => openFiles($))

  // 帯の「ファイル一覧」ボタン（コマンドを打たずにマウスだけで開けるように）。
  //   mod が置ける入口は帯（AbovePrompt）とペインだけで、ツールバーやメニューの口は無い（reference の Render sites）。
  //   session-memo の帯と1行に並ぶよう、後の mod の帯（next の結果）を左に伸ばし、ボタンを右端に置く
  //   （session-memo が外側でも、こちらを同じ行の右に置く）。数字の hotkey は付けない（空の入力欄で数字を打つと押される）
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const theirs = await next(e)
    const { Box, Button } = $.ui.resolve(e)
    const button = Button({ key: 'files-open', label: 'ファイル一覧', plain: true, dimColor: true, onPress: () => openFiles($) })
    const left = Box({ flexDirection: 'column', flexGrow: 1, children: theirs ? [theirs] : [] })
    return Box({ flexDirection: 'row', columnGap: 2, children: [left, button] })
  })

  // プレビューのペイン
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PREVIEW) return next(e)
    const { Box, Text, Button, Markdown } = $.ui.resolve(e)
    if (!preview || !root) {
      return Box({ flexDirection: 'column', children: [Text({ children: ['ファイル一覧からファイルを押してください'] })] })
    }
    const rel = preview.rel
    const header = Box({
      flexDirection: 'row',
      columnGap: 2,
      children: [
        Text({ bold: true, wrap: 'truncate-start', children: [rel] }),
        Button({ key: 'preview-ref', label: '@参照', plain: true, onPress: () => insertReference($, rel) }),
        Button({ key: 'preview-outside', label: '外で開く', plain: true, onPress: () => openInExplorer($, rel) }),
        Button({ key: 'preview-reload', label: '読み直す', plain: true, dimColor: true, onPress: () => openPreview($, rel) }),
      ],
    })
    if (preview.error) {
      return Box({ flexDirection: 'column', children: [header, Text({ color: 'red', children: [preview.error] })] })
    }
    const body = preview.markdown ? preview.text : fenced(preview.text, extensionOf(rel))
    const tail = preview.truncated ? [Text({ dimColor: true, children: ['…長いので先頭だけ出しています。全部は「外で開く」で'] })] : []
    return Box({ flexDirection: 'column', rowGap: 1, children: [header, Markdown({ key: 'preview-body', text: body }), ...tail] })
  })

  // 一覧のペイン
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    if (!root) {
      return Box({ flexDirection: 'column', children: [Text({ children: ['/files で開き直してください'] })] })
    }
    const width = Math.max(10, Math.min(RULE_MAX, Number(e.props && e.props.bodyColumns) || RULE_MAX))
    const rule = () => Text({ dimColor: true, children: ['─'.repeat(width)] })
    const header = Box({
      flexDirection: 'row',
      columnGap: 2,
      children: [
        Text({ bold: true, wrap: 'truncate-start', children: ['📂 ' + root.shown] }),
        Button({ key: 'reload', label: '読み直す', plain: true, onPress: () => reloadAll($) }),
        Button({ key: 'open-root', label: 'エクスプローラーで開く', plain: true, onPress: () => openInExplorer($, '') }),
      ],
    })
    // 1行: 字下げ・アイコンつきの名前（押す）・右端に「外で開く」。触れた行は色を付け、行の下に区切り線
    const line = (rel, depth, main, side) =>
      Box({
        key: keyOf('row', rel),
        flexDirection: 'column',
        children: [
          Box({
            key: keyOf('line', rel),
            flexDirection: 'row',
            columnGap: 1,
            paddingX: 1,
            hover: { backgroundColor: 'gray' },
            children: [
              Text({ children: ['   '.repeat(depth)] }),
              Box({ flexGrow: 1, children: [main] }),
              ...(side ? [side] : []),
            ],
          }),
          rule(),
        ],
      })
    const outside = (rel) => Button({ key: keyOf('out', rel), label: '外で開く', plain: true, dimColor: true, onPress: () => openInExplorer($, rel) })
    // 右端: 「@」（入力欄へ @参照）と「外で開く」。リンクは行き先が作業ディレクトリの外のことがあるので「外で開く」だけ
    const actions = (rel) =>
      Box({
        key: keyOf('acts', rel),
        flexDirection: 'row',
        columnGap: 1,
        children: [Button({ key: keyOf('ref', rel), label: '@', plain: true, dimColor: true, onPress: () => insertReference($, rel) }), outside(rel)],
      })
    const lines = visibleRows().map((row) => {
      if (row.type === 'loading') {
        return line(row.rel + '#wait', row.depth, Text({ dimColor: true, children: ['読み込み中…'] }))
      }
      if (row.type === 'error') {
        return line(row.rel + '#err', row.depth, Text({ color: 'red', children: [row.text] }))
      }
      if (row.type === 'more') {
        return line(row.rel + '#more', row.depth, Text({ dimColor: true, children: ['…ほか ' + row.count + ' 件（エクスプローラーで見てください）'] }))
      }
      const { entry, rel } = row
      if (entry.kind === 'dir') {
        const mark = expanded.has(rel) ? '▾ ' : '▸ '
        const busy = loading.has(rel) ? ' …' : ''
        return line(
          rel,
          row.depth,
          Button({ key: keyOf('dir', rel), label: mark + '📁 ' + entry.name + '/' + busy, plain: true, onPress: () => toggleDir($, rel) }),
          actions(rel),
        )
      }
      if (entry.isLink) {
        return line(rel, row.depth, Button({ key: keyOf('link', rel), label: '🔗 ' + entry.name, plain: true, onPress: () => pressLink($, rel) }), outside(rel))
      }
      const hint = isTextFile(entry.name) ? '' : ' ↗'
      return line(
        rel,
        row.depth,
        Button({ key: keyOf('file', rel), label: iconOf(entry) + ' ' + entry.name + hint, plain: true, onPress: () => pressFile($, rel) }),
        actions(rel),
      )
    })
    const footer = notice ? [Text({ dimColor: true, wrap: 'truncate-end', children: [notice] })] : []
    const legend = Text({ dimColor: true, children: ['押す: 文字のファイルはここで見る・↗ は既定のアプリで開く・@ は入力欄へ @参照'] })
    return Box({ flexDirection: 'column', children: [header, legend, ...footer, rule(), ...lines] })
  })
}

